109 | // Shoe represents a multi-deck dealing shoe.
110 | type Shoe struct {
111 | 	mu           sync.Mutex
112 | 	cards        []Card
113 | 	dealtCards   []Card
114 | 	totalDecks   int
115 | 	cutCardIndex int
116 | 	rng          *rand.Rand
