120 | // ShoeOption defines functional options for Shoe creation.
121 | type ShoeOption func(*Shoe)
122 | 
123 | // WithCutCardPenetration sets the shoe cut card penetration percentage (e.g. 0.75 = 75%).
124 | func WithCutCardPenetration(penetration float64) ShoeOption {
125 | 	return func(s *Shoe) {
126 | 		if penetration <= 0 || penetration >= 1.0 {
127 | 			penetration = 0.75
128 | 		}
129 | 		total := s.totalDecks * 52
130 | 		s.cutCardIndex = int(float64(total) * penetration)
131 | 	}
132 | }
133 | 
134 | // WithCustomRNG sets a custom random generator (useful for reproducible tests).
135 | func WithCustomRNG(rng *rand.Rand) ShoeOption {
136 | 	return func(s *Shoe) {
137 | 		s.rng = rng
138 | 	}
139 | }
