148 | // NewShoe initializes and shuffles a multi-deck shoe (1 to 8 decks).
149 | func NewShoe(numDecks int, opts ...ShoeOption) *Shoe {
150 | 	if numDecks < 1 {
151 | 		numDecks = 1
152 | 	}
153 | 	if numDecks > 8 {
154 | 		numDecks = 8
155 | 	}
156 | 
157 | 	s := &Shoe{
158 | 		totalDecks: numDecks,
159 | 		rng:        rand.New(rand.NewSource(time.Now().UnixNano())),
160 | 	}
161 | 
162 | 	// Default cut card index: 75%
163 | 	s.cutCardIndex = int(float64(numDecks*52) * 0.75)
164 | 
165 | 	for _, opt := range opts {
166 | 		opt(s)
167 | 	}
168 | 
169 | 	s.ResetAndShuffle()
170 | 	return s
171 | }
172 | 
173 | // ResetAndShuffle refills the shoe with full decks and performs a Fisher-Yates shuffle.
174 | func (s *Shoe) ResetAndShuffle() {
175 | 	s.mu.Lock()
176 | 	defer s.mu.Unlock()
177 | 
178 | 	totalCards := s.totalDecks * 52
179 | 	s.cards = make([]Card, 0, totalCards)
180 | 	s.dealtCards = make([]Card, 0, totalCards)
181 | 
182 | 	allSuits := []Suit{Spades, Hearts, Diamonds, Clubs}
183 | 	allRanks := []Rank{Two, Three, Four, Five, Six, Seven, Eight, Nine, Ten, Jack, Queen, King, Ace}
184 | 
185 | 	for d := 0; d < s.totalDecks; d++ {
186 | 		for _, suit := range allSuits {
187 | 			for _, rank := range allRanks {
188 | 				s.cards = append(s.cards, Card{Rank: rank, Suit: suit})
189 | 			}
190 | 		}
191 | 	}
192 | 
193 | 	// Fisher-Yates shuffle
194 | 	for i := len(s.cards) - 1; i > 0; i-- {
195 | 		j := s.rng.Intn(i + 1)
196 | 		s.cards[i], s.cards[j] = s.cards[j], s.cards[i]
197 | 	}
198 | }
