200 | // Deal pops the top card from the shoe. If empty, it automatically resets & shuffles.
201 | func (s *Shoe) Deal() Card {
202 | 	s.mu.Lock()
203 | 	if len(s.cards) == 0 {
204 | 		s.mu.Unlock()
205 | 		s.ResetAndShuffle()
206 | 		s.mu.Lock()
207 | 	}
208 | 
209 | 	idx := len(s.cards) - 1
210 | 	card := s.cards[idx]
211 | 	s.cards = s.cards[:idx]
212 | 	s.dealtCards = append(s.dealtCards, card)
213 | 
214 | 	cb := s.onDeal
215 | 	s.mu.Unlock()
216 | 
217 | 	if cb != nil {
218 | 		cb(card)
219 | 	}
220 | 	return card
221 | }
