249 | // RemainingDecks returns remaining decks estimated as a float (cards / 52.0).
250 | func (s *Shoe) RemainingDecks() float64 {
251 | 	rem := float64(s.RemainingCards()) / 52.0
252 | 	if rem < 0.5 {
253 | 		return 0.5 // Bound minimum remaining decks to prevent division by zero in card counting
254 | 	}
255 | 	return rem
256 | }
257 | 
258 | // Penetration returns the percentage of the shoe dealt (0.0 to 1.0).
259 | func (s *Shoe) Penetration() float64 {
260 | 	s.mu.Lock()
261 | 	defer s.mu.Unlock()
262 | 	total := s.totalDecks * 52
263 | 	if total == 0 {
264 | 		return 0
265 | 	}
266 | 	return float64(len(s.dealtCards)) / float64(total)
267 | }
